<?php
require_once __DIR__ . '/config/database.php';require_once __DIR__ . '/includes/layout.php';
$courses=$pdo->query("SELECT c.*,(SELECT COUNT(*) FROM enrollments e WHERE e.course_id=c.id) AS learners FROM courses c WHERE c.status='active' ORDER BY c.title")->fetchAll();start_page('Browse courses','courses'); ?>
<div class="mb-5 flex flex-wrap items-end justify-between gap-3"><p class="muted max-w-xl">Choose a course that fits your goals. Pay the five-shilling enrollment fee to unlock your learning space.</p><span class="badge badge-pending">Enrollment KSh 5.00</span></div><div class="grid gap-4 md:grid-cols-2 xl:grid-cols-3"><?php foreach($courses as $course): ?><article class="card course-card"><div class="flex items-center justify-between"><span class="course-code"><?= e($course['code']) ?></span><span class="text-xs text-slate-400"><?= (int)$course['learners'] ?> learners</span></div><h2 class="mt-4 text-lg font-bold text-slate-800"><?= e($course['title']) ?></h2><p class="mt-2 flex-1 text-sm leading-6 text-slate-600"><?= e($course['description']) ?></p><div class="mt-4 flex justify-between border-t border-slate-100 pt-3 text-xs text-slate-500"><span><?= e($course['duration']) ?></span><span>One-time KSh 5</span></div><?php if(current_user()&&current_user()['role']==='student'): ?><a class="btn-primary mt-4 w-full" href="<?= e(app_url('student/dashboard.php?course='.(int)$course['id'])) ?>">View course & enroll</a><?php elseif(!current_user()): ?><a class="btn-primary mt-4 w-full" href="<?= e(app_url('login.php')) ?>">Sign in to enroll</a><?php endif ?></article><?php endforeach ?></div><?php if(!$courses): ?><div class="card muted">No courses are available at the moment.</div><?php endif ?><?php end_page(); ?>
